-- Rename the index ix_customers_city to ix_cust_city
EXEC sp_rename
    @objname = N'sales.customers.ix_customers_city',
    @newname = N'ix_cust_city',
    @objtype = N'INDEX';

-- Confirm the new name
SELECT name, type_desc
FROM sys.indexes
WHERE object_id = OBJECT_ID('sales.customers')
  AND name = N'ix_cust_city';
